def transform(grid):
    n = len(grid[0])
    c = next(i for i, v in enumerate(grid[0]) if v == 2)
    out = [[0] * n for _ in range(n)]
    for r in range(n):
        if r <= c:
            out[r][c-r] = 2
            out[r][c+r] = 2
        lo, hi = max(0, c-r+1), min(n-1, c+r-1)
        for j in range(lo, hi+1):
            if j % 4 == (r+2) % 4: out[r][j] = 1
        if r > c:
            for j in range(n):
                if j % 4 == (r+2) % 4: out[r][j] = 1
    return out
